#include <WiFi.h>
#include "Adafruit_MQTT.h"
#include "Adafruit_MQTT_Client.h"
#include "secrets.h"

// ESP32-WROOM-32 + 4CH Relay ACTIVE-HIGH
// GPIO25=Relay1, GPIO26=Relay2, GPIO27=Relay3, GPIO33=Relay4
// ACTIVE-HIGH: HIGH = ON, LOW = OFF

#define Relay1 25
#define Relay2 26
#define Relay3 27
#define Relay4 33

#define WLAN_SSID "K42"
#define WLAN_PASS "13136161"

#define AIO_SERVER "io.adafruit.com"
#define AIO_SERVERPORT 1883
#define AIO_USERNAME "Aligg"

// Replace with your NEW Adafruit IO key.
#define AIO_KEY ""

WiFiClient client;

Adafruit_MQTT_Client mqtt(
  &client, AIO_SERVER, AIO_SERVERPORT,
  AIO_USERNAME, AIO_KEY
);

Adafruit_MQTT_Subscribe Light1 =
  Adafruit_MQTT_Subscribe(&mqtt, AIO_USERNAME "/feeds/Relay1");
Adafruit_MQTT_Subscribe Light2 =
  Adafruit_MQTT_Subscribe(&mqtt, AIO_USERNAME "/feeds/Relay2");
Adafruit_MQTT_Subscribe Light3 =
  Adafruit_MQTT_Subscribe(&mqtt, AIO_USERNAME "/feeds/Relay3");
Adafruit_MQTT_Subscribe Light4 =
  Adafruit_MQTT_Subscribe(&mqtt, AIO_USERNAME "/feeds/Relay4");

void allRelaysOff();
void connectWiFi();
bool connectMQTT();

void setup() {
  Serial.begin(115200);
  delay(500);

  pinMode(Relay1, OUTPUT);
  pinMode(Relay2, OUTPUT);
  pinMode(Relay3, OUTPUT);
  pinMode(Relay4, OUTPUT);

  // ACTIVE-HIGH: LOW = OFF
  allRelaysOff();

  Serial.println();
  Serial.println("ESP32 Home Automation - ACTIVE HIGH");
  connectWiFi();

  mqtt.subscribe(&Light1);
  mqtt.subscribe(&Light2);
  mqtt.subscribe(&Light3);
  mqtt.subscribe(&Light4);

  Serial.println("System ready.");
}

void loop() {
  if (WiFi.status() != WL_CONNECTED) {
    connectWiFi();
  }

  if (!connectMQTT()) {
    delay(2000);
    return;
  }

  Adafruit_MQTT_Subscribe *subscription;

  while ((subscription = mqtt.readSubscription(1000))) {

    if (subscription == &Light1) {
      int state = atoi((char *)Light1.lastread);
      digitalWrite(Relay1, state ? HIGH : LOW);
      Serial.print("Relay 1 -> ");
      Serial.println(state ? "ON" : "OFF");
    }

    if (subscription == &Light2) {
      int state = atoi((char *)Light2.lastread);
      digitalWrite(Relay2, state ? HIGH : LOW);
      Serial.print("Relay 2 -> ");
      Serial.println(state ? "ON" : "OFF");
    }

    if (subscription == &Light3) {
      int state = atoi((char *)Light3.lastread);
      digitalWrite(Relay3, state ? HIGH : LOW);
      Serial.print("Relay 3 -> ");
      Serial.println(state ? "ON" : "OFF");
    }

    if (subscription == &Light4) {
      int state = atoi((char *)Light4.lastread);
      digitalWrite(Relay4, state ? HIGH : LOW);
      Serial.print("Relay 4 -> ");
      Serial.println(state ? "ON" : "OFF");
    }
  }

  delay(10);
}

void allRelaysOff() {
  digitalWrite(Relay1, LOW);
  digitalWrite(Relay2, LOW);
  digitalWrite(Relay3, LOW);
  digitalWrite(Relay4, LOW);
}

void connectWiFi() {
  Serial.print("Connecting to WiFi: ");
  Serial.println(WLAN_SSID);

  WiFi.mode(WIFI_STA);
  WiFi.begin(WLAN_SSID, WLAN_PASS);

  int attempts = 0;
  while (WiFi.status() != WL_CONNECTED && attempts < 30) {
    delay(500);
    Serial.print(".");
    attempts++;
  }
  Serial.println();

  if (WiFi.status() == WL_CONNECTED) {
    Serial.println("WiFi connected.");
    Serial.print("IP: ");
    Serial.println(WiFi.localIP());
  } else {
    Serial.println("WiFi connection failed. Will retry.");
  }
}

bool connectMQTT() {
  if (mqtt.connected()) {
    return true;
  }

  Serial.print("Connecting to Adafruit IO MQTT...");

  for (uint8_t attempt = 0; attempt < 5; attempt++) {
    int8_t ret = mqtt.connect();

    if (ret == 0) {
      Serial.println(" connected!");
      return true;
    }

    Serial.println();
    Serial.print("MQTT error: ");
    Serial.println(mqtt.connectErrorString(ret));

    mqtt.disconnect();
    delay(2000);
  }

  Serial.println("MQTT unavailable. Will retry later.");
  return false;
}
